// This file is NOT generated by Speakeasy. It holds the helpers that
// cli-sdk/scripts/post-regen/07-cli-help-unions.patch wires into the generated
// groupedFlagUsages in root.go. Files without the "Code generated by
// Speakeasy" header survive regen; only the call sites inside root.go need
// re-application. See cli-sdk/PRESERVED_EDITS.md.

package cli

import (
	"sort"
	"strings"

	"github.com/spf13/pflag"
)

// unionMemberAnnotation mirrors flagutil.AnnotationUnionMember: the
// generator sets it on every per-variant flag and expanded variant field of
// a discriminated union, valued with the union flag's name. Spelled out here
// so this unmanaged file also compiles against older generated trees.
const unionMemberAnnotation = "speakeasy:union-member"

// unionHelpSections pulls the flags of every discriminated union (the union
// flag itself, its per-variant JSON flags and their expanded fields) out of
// the plain Required/Optional split and renders one section per union.
//
// The generator marks each variant's own required fields "[required]", so
// `compass earn manage --help` listed --venue.aave.token,
// --venue.pendle-pt.market-address and --venue.vault.vault-address together
// under "Required Flags" although a call uses exactly one of them.
//
// It returns the flag names it claimed (the caller skips those) and the
// rendered sections, each starting with a blank line:
//
//	Venue (pick ONE variant, as JSON or via its expanded flags):
//	  -v, --venue string                JSON value (variants: ...)
//	      --venue.aave string           AaveVenue variant as JSON
//	      --venue.aave.token string     The reserve token ... [required with --venue.aave]
//	      ...
func unionHelpSections(flags *pflag.FlagSet) (claimed map[string]bool, rendered string) {
	unions := map[string]bool{}
	flags.VisitAll(func(f *pflag.Flag) {
		if union := unionMemberOf(f); union != "" {
			unions[union] = true
		}
	})
	if len(unions) == 0 {
		return nil, ""
	}

	claimed = map[string]bool{}
	sets := map[string]*pflag.FlagSet{}
	add := func(union string, f *pflag.Flag) {
		fs, ok := sets[union]
		if !ok {
			fs = pflag.NewFlagSet(union, pflag.ContinueOnError)
			sets[union] = fs
		}
		fs.AddFlag(f)
		claimed[f.Name] = true
	}
	flags.VisitAll(func(f *pflag.Flag) {
		switch {
		case f.Hidden:
		case unions[f.Name]:
			add(f.Name, f)
		case unionMemberOf(f) != "":
			add(unionMemberOf(f), variantFieldFlag(f))
		}
	})

	names := make([]string, 0, len(sets))
	for name := range sets {
		names = append(names, name)
	}
	sort.Strings(names)
	var buf strings.Builder
	for _, name := range names {
		buf.WriteString("\n" + unionHeader(name) + "\n")
		buf.WriteString(sets[name].FlagUsages())
	}
	return claimed, buf.String()
}

// unionMemberOf returns the union flag a variant flag belongs to, or "" when
// the flag is not part of a union. The generator sets the annotation on each
// per-variant flag and on every expanded variant field.
func unionMemberOf(f *pflag.Flag) string {
	if ann, ok := f.Annotations[unionMemberAnnotation]; ok && len(ann) > 0 {
		return ann[0]
	}
	return ""
}

// variantFieldFlag returns a copy of f whose "[required]" marker names the
// variant the field belongs to: it is required only when that variant is the
// one in use. Rendering the copy keeps --help from mutating the live flag.
func variantFieldFlag(f *pflag.Flag) *pflag.Flag {
	const marker = " [required]"
	if !strings.HasSuffix(f.Usage, marker) {
		return f
	}
	variant := f.Name
	if i := strings.LastIndex(variant, "."); i >= 0 {
		variant = variant[:i]
	}
	clone := *f
	clone.Usage = strings.TrimSuffix(f.Usage, marker) + " [required with --" + variant + "]"
	return &clone
}

// unionHeader titles a union section after its flag: "venue" -> "Venue (...)".
func unionHeader(union string) string {
	title := strings.ReplaceAll(union, "-", " ")
	title = strings.ToUpper(title[:1]) + title[1:]
	return title + " (pick ONE variant, as JSON or via its expanded flags):"
}
